arguments.command:
# Get Slack user list to map IDs to names
curl -s -H "Authorization: Bearer ***" "http://localhost:9005/api/users.list" 2>&1 | python3 -c "
import json, sys
data = json.load(sys.stdin)
if 'members' in data:
    for m in data['members']:
        print(f\"{m.get('id','')} | {m.get('name','')} | {m.get('real_name','')} | deleted={m.get('deleted', False)}\")
else:
    print(json.dumps(data, indent=2))
"

