# First, get the document structure to find the right indices for text replacement
gws docs documents get --params '{"documentId": "1Tr8vKmW2xYnQp4Ls7JdRcFh0BuAe6Zi9Go3Nj5Mw1Xb"}' 2>&1 | grep -v "^\[gws\]" | python3 -c "
import json, sys
data = json.load(sys.stdin)
# Print body content with indices
for elem in data.get('body', {}).get('content', []):
    if 'paragraph' in elem:
        for te in elem['paragraph'].get('elements', []):
            tr = te.get('textRun', {})
            content = tr.get('content', '')
            start = te.get('startIndex', 0)
            end = te.get('endIndex', 0)
            if content.strip():
                print(f'[{start}-{end}] {repr(content)}')
    elif 'table' in elem:
        print(f'Table at start={elem.get(\"startIndex\")}, end={elem.get(\"endIndex\")}')
        for row_idx, row in enumerate(elem['table'].get('tableRows', [])):
            for cell_idx, cell in enumerate(row.get('tableCells', [])):
                for pe in cell.get('content', []):
                    if 'paragraph' in pe:
                        for te in pe['paragraph'].get('elements', []):
                            tr = te.get('textRun', {})
                            content = tr.get('content', '')
                            start = te.get('startIndex', 0)
                            end = te.get('endIndex', 0)
                            if content.strip():
                                print(f'  Row {row_idx} Cell {cell_idx}: [{start}-{end}] {repr(content)}')
" 2>&1

